import{_ as a,o as i,c as r,a5 as t}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/repository/customer-drive-overflow/test.md","filePath":"feature/repository/customer-drive-overflow/test.md"}'),n={name:"feature/repository/customer-drive-overflow/test.md"};function o(s,e,l,d,c,p){return i(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h1><ul><li>Free/paid with Drive available =&gt; USER_GDRIVE. Drive full + active paid with S3 available =&gt; SYSTEM_S3. Free/expired/full S3 =&gt; actionable failure.</li><li>Timeout/revoked grant never routes to S3. Idempotent retry retains selected provider.</li><li>Concurrent reservation capacity/quota, release/purge accounting, immutable provider and reads after plan expiry.</li><li>Owner/Manager connect; Creator/Client forbidden. Creator creates internal files; only Owner/Manager share Client audience.</li><li>OAuth state single use and actor/workspace bound; altered PKCE/state/code denied; tokens absent from API/logs; reconnect same account.</li><li>Idempotent folder provisioning by ID; unicode names; same-name agencies/workspaces isolated.</li><li>Private preview, range/video, expiration, disconnect, missing/deleted external object; no public Drive permissions.</li><li>Frontend connect completion, denial/retry, disabled/unconfigured, vi/en parity, light/dark and narrow viewport.</li></ul><p>Status: implementation in progress; no live migration or OAuth connection performed.</p><h2 id="implementation-evidence" tabindex="-1">Implementation evidence <a class="header-anchor" href="#implementation-evidence" aria-label="Permalink to &quot;Implementation evidence&quot;">​</a></h2><ul><li>Added source: CustomerDriveConnectionService/API/ObjectStore/Links, authenticated workspace management controller, capability media controller, encrypted grant storage, DriveOperationLease and Drive-first paid-overflow routing.</li><li>Backend tests cover Drive preference, paid-only overflow, expiration, generic failures, simultaneous reservations, commit during capacity sampling, shared Google account across agencies, actor-bound single-use OAuth state, disconnect fencing, recovery after uncertain copy/deletion, operation-bound expiring capabilities, exact provider capacity classification and single URI encoding.</li><li>Frontend verification includes Owner/Manager controls, Creator/Client isolation, callback replay avoidance/history cleanup and one bounded fresh-reservation retry on capacity failure. Repository regression also exercises previous view/update/download/Trash workflows.</li><li>Runtime remains disabled by default; live Google/production rollout is not verified by local mocks and disposable database tests. Follow plan.md before activation.</li></ul><h2 id="final-local-verification-—-2026-10-26" tabindex="-1">Final local verification — 2026-10-26 <a class="header-anchor" href="#final-local-verification-—-2026-10-26" aria-label="Permalink to &quot;Final local verification — 2026-10-26&quot;">​</a></h2><ul><li>Business full Maven suite: 1288 tests, 0 failures, 0 errors, 93 existing conditional skips. Customer Drive tests: 14 tests, no skips, including real disposable PostgreSQL/Mongo setup.</li><li>Gateway full Maven suite:47 tests, 0 failures/errors/skips. Includes capability IP throttling/fail-closed behavior and capability-query log redaction.</li><li>Web: TypeScript/build passed;14 unit tests passed; changed source ESLint clean. Existing bundle-size advisory remains.</li><li>Repository Playwright regression:26 tests passed. Two additional Owner/Manager keyboard checks passed;390px light/dark screenshots visually inspected.</li><li>Git diff whitespace checks passed. Migration applied only to disposable test databases.</li></ul><h2 id="standards-review" tabindex="-1">Standards review <a class="header-anchor" href="#standards-review" aria-label="Permalink to &quot;Standards review&quot;">​</a></h2><p>Initial gateway YAML, remote-I/O transaction, recovery and UI error-state findings were fixed. Final independent recheck found no remaining high-impact issue. Small existing repository conventions were preserved; this is not a claim that all pre-existing source is lint-clean.</p><h2 id="spec-review" tabindex="-1">Spec review <a class="header-anchor" href="#spec-review" aria-label="Permalink to &quot;Spec review&quot;">​</a></h2><p>Initial stale-capacity, shared-account, purchased-quota, Owner access, recovery, encoding and disconnect-race findings were fixed and covered by tests. Final independent recheck found no remaining high-impact issue.</p><p>The user explicitly requested keeping all changes uncommitted for later consolidation. No work was staged or committed.</p><h2 id="_2026-10-27-br-update" tabindex="-1">2026-10-27 BR update <a class="header-anchor" href="#_2026-10-27-br-update" aria-label="Permalink to &quot;2026-10-27 BR update&quot;">​</a></h2><p>Disconnect A removes BrandHub-managed Drive files/folders, invalidates materials and old callbacks, releases quota and allows B. Failure retains retry state and blocks B; other providers/agencies remain. Targeted validation: 13 integration + 3 API tests passed with local Testcontainers; 7 Playwright Drive tests passed with mocked APIs.</p><ul><li>New workspace folders use workspaces.name, including Unicode. Existing workspace_1 mapping is renamed to the workspace name, retains folder ID, and never creates a duplicate. Same-name folders require no PATCH.</li></ul><p>Workspace naming validation: 14 integration + 4 API tests passed, none skipped. Mapped folder rename preserves ID, handles Unicode and skips PATCH when name already matches. No live rename performed: current configured database contains no workspace_drive_folders mapping. Restart business to load the naming change; existing mapped folders sync when folder(workspace) next resolves.</p>',16)])])}const v=a(n,[["render",o]]);export{m as __pageData,v as default};
